// Pseudo-test sketch for idempotent POST
async function testIdempotentPost(client, key, payload) {
  const r1 = await client.post('/payments', payload, { idempotencyKey: key });
  const r2 = await client.post('/payments', payload, { idempotencyKey: key });
  if (r1.id !== r2.id) throw new Error('Ids differ on retry');
}
```

